<?php

declare(strict_types=1);

namespace Src\Shared\Domain\Contracts;

interface ImageStorage
{
    /** Keep a copy of an image under a name generated by the server and answer its path. */
    public function store(string $directory, string $sourcePath, string $extension): string;

    /** Delete a stored image; a missing image is ignored. */
    public function delete(string $path): void;

    /** Public address of a stored image. */
    public function url(string $path): string;
}
